import numpy as np

demo_input = [
    [1, 0, 0, 0, 9],
    [0, 5, 0, 8, 0],
    [0, 0, 7, 0, 0],
    [0, 8, 0, 5, 0],
    [9, 0, 0, 0, 1]
]

inp = np.array(demo_input)
demo_output = np.array([
    [1, 5, 9],
    [8, 7, 8],
    [9, 5, 1]
])

# Define the mapping
def get_input_pos(i, j):
    """Map output coordinate (i,j) to input coordinate"""
    if i == 0:
        if j == 0: return (0, 0)
        elif j == 1: return (1, 1)
        elif j == 2: return (0, 4)
    elif i == 1:
        if j == 0: return (3, 1)
        elif j == 1: return (2, 2)
        elif j == 2: return (1, 3)
    elif i == 2:
        if j == 0: return (4, 0)
        elif j == 1: return (3, 3)
        elif j == 2: return (4, 4)
    return (0, 0)

# Verify
print("Verifying mapping:")
for i in range(3):
    for j in range(3):
        in_r, in_c = get_input_pos(i, j)
        val = inp[in_r, in_c]
        out_val = demo_output[i, j]
        status = "✓" if val == out_val else f"(expected {out_val})"
        print(f"  output[{i},{j}] <- input[{in_r},{in_c}]={val} {status}")

# Now apply to the test input
test_input = [
    [7, 0, 0, 0, 5],
    [0, 6, 0, 4, 0],
    [0, 0, 2, 0, 0],
    [0, 4, 0, 6, 0],
    [5, 0, 0, 0, 7]
]

print("\nApplying to test input:")
test_out = []
for i in range(3):
    row = []
    for j in range(3):
        in_r, in_c = get_input_pos(i, j)
        val = test_input[in_r][in_c] if test_input[in_r][in_c] != 0 else test_input[in_r][in_c]
        row.append(val)
    test_out.append(row)
    print(f"output row {i}: {row}")

print(f"\nFinal output: {test_out}")
